import re, openpyxl
s=open('xx/xl/worksheets/sheet1.xml').read()
mapping={}
for row in re.findall(r'<row\b.*?</row>', s, re.S):
    for c in re.findall(r'<c\b[^>]*>', row):
        r=re.search(r'r="([A-Z]+\d+)"', c)
        st=re.search(r's="(\d+)"', c)
        if r and st:
            mapping[r.group(1)]=int(st.group(1))
wb=openpyxl.load_workbook('1_52021_answer_inconsistent_color_6113_input.xlsx')
ws=wb.active
for coord in ['A5','B6','B16','A6','A16','B5','B15']:
    c=ws[coord]
    print(coord, 'xml_s=', mapping.get(coord), 'openpyxl_style_id=', c.style_id, 'pattern', c.fill.patternType, 'fg', c.fill.fgColor.rgb)
